/* Rentcam CMS product actions */
(function(){
  if(!location.pathname.startsWith('/cms'))return;
  const esc=s=>String(s||'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));
  const cfg=()=>window.RENTCAM_CMS_CONFIG||null;
  const custom=id=>(cfg()?.customProducts||[]).find(x=>String(x.id)===String(id));
  const ov=id=>(cfg()?.productOverrides||{})[id]||{};
  const isOn=id=>{const x=custom(id)||ov(id);return x.active!==false&&x.deleted!==true};
  function css(){if(document.getElementById('rc-prod-actions-css'))return;const s=document.createElement('style');s.id='rc-prod-actions-css';s.textContent='.rcpa{display:flex;gap:6px;align-items:center;white-space:nowrap}.rcpa .danger{color:#c62828!important;background:#fff4f4!important;border-color:#ffd2d2!important}.rcmodal{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.48);display:grid;place-items:center;padding:18px}.rcbox{width:min(440px,100%);background:#fff;border-radius:16px;padding:20px;box-shadow:0 24px 70px rgba(0,0,0,.25)}.rcbox h3{margin:0 0 8px;font-size:20px}.rcbox p{color:#666;line-height:1.5}.rcname{display:block;background:#f5f6f7;padding:10px 12px;border-radius:10px;font-weight:800;color:#111;margin:10px 0}.rcfoot{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.rcfoot button{height:40px;padding:0 15px;border-radius:9px;border:1px solid #ddd;background:#fff;font-weight:800}.rcfoot .danger{background:#d92d20;color:#fff;border-color:#d92d20}.rctoast{position:fixed;right:20px;top:82px;z-index:100000;background:#17191c;color:#fff;padding:11px 14px;border-radius:10px;font-weight:800;font-size:13px}';document.head.appendChild(s)}
  function toast(t){const x=document.createElement('div');x.className='rctoast';x.textContent=t;document.body.appendChild(x);setTimeout(()=>x.remove(),1800)}
  function saveAndRefresh(msg){document.querySelector('button[data-act="save"]')?.click();setTimeout(()=>{document.querySelector('[data-nav="products"]')?.click();toast(msg)},350)}
  function toggle(id){const c=cfg();if(!c)return;const x=custom(id);const next=!isOn(id);if(x){x.active=next;if(next)x.deleted=false}else{c.productOverrides=c.productOverrides||{};c.productOverrides[id]={...(c.productOverrides[id]||{}),active:next,deleted:next?false:(c.productOverrides[id]?.deleted||false)}}saveAndRefresh(next?'Produk diaktifkan.':'Produk dinonaktifkan.')}
  function confirmDelete(id,row){const c=cfg();if(!c)return;const x=custom(id),name=row?.querySelector('.v5-prod b')?.textContent||id;const m=document.createElement('div');m.className='rcmodal';m.innerHTML='<div class="rcbox"><h3>Hapus Produk</h3><p>Yakin ingin menghapus produk ini?</p><span class="rcname">'+esc(name)+'</span><p style="font-size:12px">'+(x?'Produk custom akan dihapus permanen.':'Produk bawaan akan di-soft delete dan bisa dipulihkan dari Status & Hapus Data.')+'</p><div class="rcfoot"><button data-cancel>Batal</button><button class="danger" data-ok>Hapus</button></div></div>';m.onclick=e=>{if(e.target===m||e.target.closest('[data-cancel]'))m.remove();if(e.target.closest('[data-ok]')){if(x){c.customProducts=(c.customProducts||[]).filter(p=>String(p.id)!==String(id));if(c.productOverrides)delete c.productOverrides[id]}else{c.productOverrides=c.productOverrides||{};c.productOverrides[id]={...(c.productOverrides[id]||{}),active:false,deleted:true,deletedAt:new Date().toISOString()}}m.remove();saveAndRefresh('Produk berhasil dihapus.')}};document.body.appendChild(m)}
  function patch(){css();document.querySelectorAll('button[data-act="edit-product"][data-id]').forEach(edit=>{const td=edit.closest('td');if(!td||td.dataset.rcpa)return;td.dataset.rcpa='1';const id=edit.dataset.id;const w=document.createElement('div');w.className='rcpa';const t=document.createElement('button');t.className='v5-btn';t.textContent=isOn(id)?'Nonaktif':'Aktifkan';t.dataset.toggleProduct=id;const d=document.createElement('button');d.className='v5-btn danger';d.textContent='Hapus';d.dataset.deleteProduct=id;td.insertBefore(w,edit);w.append(t,edit,d)})}
  document.addEventListener('click',e=>{const t=e.target.closest('[data-toggle-product]');if(t){e.preventDefault();e.stopPropagation();toggle(t.dataset.toggleProduct);return}const d=e.target.closest('[data-delete-product]');if(d){e.preventDefault();e.stopPropagation();confirmDelete(d.dataset.deleteProduct,d.closest('tr'))}},true);
  const o=new MutationObserver(patch);setTimeout(()=>{patch();const r=document.querySelector('.v5-main')||document.getElementById('app');if(r)o.observe(r,{childList:true,subtree:true})},150);
})();